def transform(grid):
    g = np.array(grid)
    out = g.copy()
    ys, xs = np.nonzero(g == 1)
    if len(ys) == 0:
        emit(out, "No lattice present; output equals input.")
        return out
    y0, y1, x0, x1 = ys.min(), ys.max(), xs.min(), xs.max()
    emit(out, "Start from the input; the lattice spans the bounding box of all 1-cells.")
    # rows
    for y in range(y0, y1 + 1):
        seg = g[y, x0:x1 + 1]
        if 2 * np.sum(seg == 1) > len(seg):
            for x in range(x0, x1 + 1):
                if out[y, x] == 0:
                    out[y, x] = 2
            emit(out, f"Row {y} is a lattice line (mostly 1s): fill its gaps with 2.")
    # columns
    for x in range(x0, x1 + 1):
        seg = g[y0:y1 + 1, x]
        if 2 * np.sum(seg == 1) > len(seg):
            for y in range(y0, y1 + 1):
                if out[y, x] == 0:
                    out[y, x] = 2
            emit(out, f"Column {x} is a lattice line (mostly 1s): fill its gaps with 2.")
    emit(out, "All lattice lines repaired; final output.")
    return out
